%[text] ## Demo1: System Identification using chirp signal
%%
%[text] ### STEP 1: CHIRP EXCITATION
%[text] load settings for the experiment
clear; close all;
projectRoot = fileparts(fileparts(mfilename("fullpath")));
addpath(projectRoot);
projectRoot = setup_project();
load(fullfile(projectRoot, "config", "data", "config.mat"));
load(fullfile(projectRoot, "config", "data", "pana_params.mat"));
%%
%[text] build simulink model "twomass\_exp\_2019a.slx" after executing this section
%[text] (build only needed 1 time.  rebuild required if you change the following parameters /or the feedback controller Kd.)
load(fullfile(projectRoot, "config", "data", "ms_q.mat"));
feedbackFlag = 1;
Ts = 1.25e-4; % sampling time (don't change)
Kd = tf(0.06,1); % open-loop system identification
sampleLength = length(ms.x(1,1,:));
u = MAX_INPUT*1/2*squeeze(ms.x(1,1,:))/(abs(max(squeeze(ms.x(1,1,:)))));
periods = 10;

u = repmat(u,[periods,1]);

% u = 0.2*ones(1,200);
N = length(u);
Tend = Ts*N;
t = (0:(N-1))*Ts;

figure; %[output:2f9b2e6c]
plot(t,u); %[output:2f9b2e6c]
set_ff = u;
set_ref = zeros(N,1);

open(fullfile(projectRoot, ModelName));
%%
%[text] execute experiment via simulink
%[text] \*make sure to close all simulink files before executing this section
open(fullfile(projectRoot, ModelName))
obtainMeasurement; %[output:424cb541]
%%
count = measurement(1,:); % data counts
input = measurement(4,:); % control input [A]
output = measurement(5,:); % loadside position [um]
velocity = measurement(6,:);
torque = measurement(7,:);
lostPackages = setdiff(1:N, count);
lostPackagesNum = length(lostPackages); % Number of Lost Packages
%[text] save experiment data
figure; %[output:38c5b8fb]
plot(count*Ts, torque, count*Ts, input); %[output:38c5b8fb]
title('position output'); %[output:38c5b8fb]
xlabel('time/s'); %[output:38c5b8fb]
ylabel('position/m'); %[output:38c5b8fb]

multsineResult = struct("input", input, "output", output, "Ts", Ts, ...
    "Tend", Tend, "ms", ms, "periods", periods, ...
    "measurement_metadata", measurement_metadata, ...
    "measurement_source_path", measurement_source_path);
f = save_experiment_result(runDir, "multsin_result", multsineResult); %[output:5162568c]
%%
%[text] ### STEP 2: TIME TREATMENT
%[text] download data
% load(f);
% load("multsin_result_2026-07-25_6.mat");
load(fullfile(projectRoot, "config", "data", "config.mat"), "bop");
%%
%[text] remove transient periods
trans = 3;                      % number of transient periods
trend = 0;                      % period trend removal flag

r0 = (1:ms.nrofs);                 % 時間可視化範囲
rn = (ms.nrofs*2+1:(2+1)*ms.nrofs);   % データ可視化範囲

% 入力と出力データの前処理
[x,time] = pretreat(input',ms.nrofs,ms.harm.fs,trans,trend);
[y,~] = pretreat(output',ms.nrofs,ms.harm.fs,trans,trend);
[v,~] = pretreat(velocity',ms.nrofs,ms.harm.fs,trans,trend);
[tor,~] = pretreat(torque',ms.nrofs,ms.harm.fs,trans,trend);

figure; %[output:3f019968]
subplot(211), plot(time(r0),x(rn,:)) %[output:3f019968]
    title('input data'), legend('input force'), ylim([-2,2]) %[output:3f019968]
subplot(212), plot(time(r0),y(rn,:)) %[output:3f019968]
    title('output data'), legend('stage position') %[output:3f019968]
    xlabel('time [s]') %[output:3f019968]
%%
%[text] ### STEP 3: NON-PARAMETRIC ESTIMATION
%[text] fft data and vizualize in freq domain position data
Pest_pos = time2frf_ml(x,y,ms);
Pest_v = time2frf_ml(x,v, ms);
Pest_tor = time2frf_ml(x,tor, ms);

figure;
bode_fdi({Pest_pos(1,1)},[Pest_pos.freq,Pest_pos.UserData.sGhat(:,1)]); %[output:12521b3a]
legend('FRF','sGhat'); %[output:12521b3a]

Pd = Pest_pos(1,1); % identified frequency response function of input -> pos
Pd.Ts = Ts;
%%
figure;
bode_fdi({Pest_v(1,1)},[Pest_v.freq,Pest_v.UserData.sGhat(:,1)]); %[output:3726e492]
legend('FRF','sGhat'); %[output:3726e492]
Pd_velocity = Pest_v(1,1);
Pd_velocity.Ts = Ts;
%%
figure;
bode_fdi({Pest_tor(1,1)},[Pest_tor.freq,Pest_tor.UserData.sGhat(:,1)]); %[output:32017049]
legend('FRF','sGhat', "Location", "northwest"); %[output:32017049]

z = tf("z",Ts);
% pd_tor_nominal = z^(-11);
Pd_torque = Pest_tor(1,1);
Pd_torque.Ts = Ts;
%%
%[text] check coherence (good if close to 0dB)
[cxy,f] = mscohere(x,y,rectwin(periods/Ts),0,periods/Ts,1/Ts); 


logical_index = ismember(ms.freq(ms.ex), ms.freq);
target_f = f(logical_index);
target_cxy = cxy(logical_index);


figure; %[output:5ce9f2fb]
plot(target_f, target_cxy) %[output:5ce9f2fb]
ax = gca; ax.XScale = 'log'; %[output:5ce9f2fb]
title("coherence")  %[output:5ce9f2fb]
ylim([0 1]); %[output:5ce9f2fb]
%%
%[text] ### Manual data fitting of system $P${"editStyle":"visual"}
%[text] True system: $P=\\frac{1}{{\\textrm{Js}}^2 +\\textrm{Ds}}${"editStyle":"visual"}
%[text] Nominal system: $P\_n =\\frac{1}{{J\_n s}^2 +D\_n s}${"editStyle":"visual"}
%[text] design $J\_n${"editStyle":"visual"} and $D\_n${"editStyle":"visual"} so $P\_n${"editStyle":"visual"} becomes close to $P${"editStyle":"visual"}.
s = tf("s");
z = tf("z",Ts);

Dn = 10^(13/20);
Jn = Dn/(10*2*pi);

Ndelay = 11; % delay step of plant [int]

% Pdn = c2d(1/(Jn*s+Dn)/s*(1/(tau*s+1)),Ts,"tustin")/z^Ndelay; % discretized nominal plant of input -> pos
Pdn = c2d(1/(Jn*s+Dn)/s,Ts,"tustin")/z^Ndelay;

% alpha = 3;
% Pdn_test = c2d(1/(Jn*s+Dn)/s/alpha*(1/(tau*s+1)),Ts,"tustin")/z^Ndelay;

bop_ = bop;
bop_.YLim = {[-160,-20];[-180,180]};
bop_.XLim = {[1,1e3]};
figure; %[output:50bb090b]
bode(Pd,Pdn,bop_); %[output:50bb090b]
% bode(Pd_velocity*c2d(1/s, Ts, "tustin"),Pdn,bop_);
legend(["$P_{d}$","$P_{n}$"],"Interpreter","latex"); %[output:50bb090b]
%%
%[text] save fitting data
plantResult = struct("Pd", Pd, "Pdn", Pdn, "Jn", Jn, "Dn", Dn, ...
    "Ndelay", Ndelay, "Ts", Ts);
save_experiment_plant(runDir, plantResult); %[output:09f12dd6]
%%
load(fullfile(projectRoot, "data", "plants", "8khz", "current.mat"));

Pdn = c2d(1/(Jn*s+Dn)/s,Ts,"tustin")/z^Ndelay;

% alpha = 3;
% Pdn_test = c2d(1/(Jn*s+Dn)/s/alpha*(1/(tau*s+1)),Ts,"tustin")/z^Ndelay;

bop_ = bop;
bop_.YLim = {[-160,-20];[-180,180]};
bop_.XLim = {[1,1e3]};
figure; %[output:88d726c1]
bode(Pd,Pdn,bop_); %[output:88d726c1]
% bode(Pd_velocity*c2d(1/s, Ts, "tustin"),Pdn,bop_);
legend(["$P_{d}$","$P_{n}$"],"Interpreter","latex"); %[output:88d726c1]
%%
S1 = load(fullfile(projectRoot, "data", "plants", "8khz", ...
    "plant_coplay_core2_2026-08-08.mat")); %[output:7a745d1a]

Pdn_si = c2d(1/(S1.Jn*s+S1.Dn)/s,Ts,"tustin")/z^S1.Ndelay;

% alpha = 3;
% Pdn_test = c2d(1/(Jn*s+Dn)/s/alpha*(1/(tau*s+1)),Ts,"tustin")/z^Ndelay;

bop_ = bop;
bop_.YLim = {[-160,-20];[-180,180]};
bop_.XLim = {[1,1e3]};
figure;
bode(S1.Pd,Pd,bop_);
% bode(Pd_velocity*c2d(1/s, Ts, "tustin"),Pdn,bop_);
legend(["Pana","Coplay"],"Interpreter","latex");
save_experiment_figures(runDir, findall(groot, "Type", "figure"));

